/**
 * The two files the browser television (apps/ops-console/tv.html) is given
 * from the Vega app, never written by hand:
 *
 *   npm run tv:build
 *
 * - tv-catalog.json — what she can watch: the three films, each with its
 *   running time, where its credits begin, who made it, and its calm
 *   points: the measured moments inside it where a note may arrive
 *   (apps/tv-vega/src/catalog/calmPoints.ts, itself generated by
 *   `npm run calm:build` from what Rekognition and ffmpeg measured). Never
 *   chosen here and never edited: calm points are measured, never guessed
 *   (AGENTS.md).
 * - tv-engine.generated.js — the television's own rules, bundled from the
 *   Vega app's source as one classic script that sets one global, `WickTv`:
 *   the Natural-Break Engine and its controller (when a note may come on
 *   screen, and when it holds the film), the second a card's buttons take
 *   no press, the two-second hold on OK, whose the Play key is, what a
 *   player's snapshot is, the home screen's waiting line, and the
 *   television's words. The page runs the very code the television runs, so
 *   the two cannot drift.
 *
 * Both are committed and served as they are (infra/ops-console.tf).
 * apps/ops-console/__tests__/tv-build.test.ts fails unless generating them
 * again gives exactly the bytes checked in.
 *
 * Importing this file builds nothing; scripts/tv-page/cli.ts runs it.
 */
import { build } from 'esbuild';
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { PROGRAMMES } from '../../packages/contracts/src/programmes.ts';
import { CALM_POINTS } from '../../apps/tv-vega/src/catalog/calmPoints.ts';

const ROOT = fileURLToPath(new URL('../..', import.meta.url));

export const CATALOG_FILE = path.join(ROOT, 'apps', 'ops-console', 'tv-catalog.json');
export const ENGINE_FILE = path.join(ROOT, 'apps', 'ops-console', 'tv-engine.generated.js');

/** One film as the page knows it. The address is the page's to make, from the films' origin (tv-core.js). */
export interface CatalogProgramme {
  readonly id: string;
  readonly title: string;
  /** The line under its title on the home screen, in English; another language says it from durationMs (words.ts programmeLine). */
  readonly line: string;
  readonly durationMs: number;
  readonly creditsPositionMs: number;
  readonly attribution: string;
  /** Measured, in order; empty for a film Wick has not measured, which then waits for a pause or the credits. */
  readonly calmPointsMs: readonly number[];
}

export function catalog(): { readonly generated: string; readonly programmes: readonly CatalogProgramme[] } {
  return {
    generated: 'by `npm run tv:build` from packages/contracts/src/programmes.ts and apps/tv-vega/src/catalog/calmPoints.ts — do not edit',
    programmes: PROGRAMMES.map((p) => ({
      id: p.id,
      title: p.title,
      line: p.line,
      durationMs: p.durationMs,
      creditsPositionMs: p.creditsPositionMs,
      attribution: p.attribution,
      calmPointsMs: (CALM_POINTS[p.id] ?? []).map((point) => point.atMs),
    })),
  };
}

/** The catalogue's file, whole. The same sources give the same text. */
export function renderCatalog(): string {
  return `${JSON.stringify(catalog(), null, 2)}\n`;
}

/** What the page is given of the television's rules, from the files they live in. */
const ENGINE_ENTRY = `
export { BreakController } from './apps/tv-vega/src/break/BreakController.ts';
export { CALM_POINT_WINDOW_MS, PAUSE_IS_BREAK_MS, SETTLED_AFTER_MS } from './apps/tv-vega/src/break/types.ts';
export { pressSettle, PRESS_SETTLE_MS } from './apps/tv-vega/src/press/settle.ts';
export { okHold, HOLD_MS } from './apps/tv-vega/src/watch/hold.ts';
export { playIsTheCards, playGoesTo, seekTarget, SEEK_STEP_MS } from './apps/tv-vega/src/watch/remoteKeys.ts';
export { PlaybackRecorder, toPlaybackDeviceEvent } from './apps/tv-vega/src/watch/playbackRecorder.ts';
export { FilmPositions } from './apps/tv-vega/src/watch/resume.ts';
export { deriveSnapshot } from './apps/tv-vega/src/player/PlayerService.ts';
export { waitingLine, backClosesOpened, backOnShownCard } from './apps/tv-vega/src/home/waiting.ts';
export { asking } from './apps/tv-vega/src/home/asked.ts';
export { unaskedLightCards } from './apps/tv-vega/src/home/light.ts';
export { newestReachCard, reachOffersToPutAway, backAnswersReach } from './apps/tv-vega/src/home/reach.ts';
export { overMantel } from './apps/tv-vega/src/mantel/mantel.ts';
export { words, programmeLine } from './apps/tv-vega/src/words/words.ts';
`;

const HEADER = `/**
 * GENERATED by \`npm run tv:build\` — do not edit.
 *
 * The television's own rules, from the Vega app's source (apps/tv-vega/src),
 * bundled as one classic script for the browser television (tv.html), which
 * reads them from the one global it sets: \`WickTv\`. Change the source and
 * run the command again; __tests__/tv-build.test.ts holds this file to it,
 * byte for byte. See scripts/tv-page/build.ts.
 */`;

/** The generated script, whole. The same source gives the same text. */
export async function renderEngine(): Promise<string> {
  const result = await build({
    absWorkingDir: ROOT,
    stdin: { contents: ENGINE_ENTRY, resolveDir: ROOT, loader: 'ts', sourcefile: 'tv-engine.ts' },
    bundle: true,
    format: 'iife',
    globalName: 'WickTv',
    platform: 'browser',
    target: 'es2022',
    charset: 'utf8',
    legalComments: 'none',
    banner: { js: HEADER },
    alias: { '@wick/contracts': path.join(ROOT, 'packages', 'contracts', 'src', 'index.ts') },
    write: false,
    logLevel: 'silent',
  });
  return result.outputFiles[0]!.text;
}

export async function main(): Promise<void> {
  writeFileSync(CATALOG_FILE, renderCatalog());
  writeFileSync(ENGINE_FILE, await renderEngine());
  console.log(`wrote ${path.relative(ROOT, CATALOG_FILE)} and ${path.relative(ROOT, ENGINE_FILE)}`);
}
